let readlineSync = require("readline-sync");
let kuler = require("kuler");
let score = 0;

let userName = readlineSync.question(kuler("👋 Enter your name: ", "#f59e0b"));
console.log(kuler(`\n🎉 Hello ${userName}! Welcome to QUIZY!\n`, "#dc2626"));

const database = {
  data: [
    {
      question: "1) What is my favorite colour?",
      options: {
        a: "Blue",
        b: "Black",
        c: "White",
        d: "Pink",
      },
      correctAnswer: "c",
    },
    {
      question: "2) Am I a mountain person or beach person?",
      options: {
        a: "Beach",
        b: "Mountain",
        c: "Neither",
        d: "Both",
      },
      correctAnswer: "b",
    },
    {
      question: "3) Do I like partying or silence?",
      options: {
        a: "Partying",
        b: "Silence",
        c: "Both",
        d: "Depends",
      },
      correctAnswer: "b",
    },
    {
      question: "4) Do I like dark or cozy theme?",
      options: {
        a: "Dark",
        b: "Cozy theme",
        c: "Bright",
        d: "None",
      },
      correctAnswer: "b",
    },
    {
      question: "5) What is my wish?",
      options: {
        a: "A trip to Paris",
        b: "Fame and money",
        c: "House on mountains",
        d: "Open a cafe",
      },
      correctAnswer: "c",
    },
  ],
};

// Empty leaderboard initially
const leaderBoard = [];

function playGame(userAnswer, correctAnswer) {
  if (userAnswer === correctAnswer) {
    console.log(kuler("✅ Correct answer!\n", "#059669"));
    score++;
  } else {
    console.log(kuler("❌ Incorrect answer", "#b91c1c"));
    console.log(kuler(`✔️ Correct answer is: ${correctAnswer}\n`, "#1d4ed8"));
  }
}

function showQuestionAndOptions(database) {
  for (let i = 0; i < database.data.length; i++) {
    console.log(kuler(database.data[i].question, "#7c3aed"));
    const opts = database.data[i].options;
    for (let key in opts) {
      console.log(kuler(`${key}) ${opts[key]}`, "#0891b2"));
    }
    let userAnswer = readlineSync.question(kuler("👉 Enter your answer: ", "#facc15")).toLowerCase();
    playGame(userAnswer, database.data[i].correctAnswer);
  }
}

function highScore(leaderBoard) {
  leaderBoard.push({ name: userName, score: score });

  leaderBoard.sort((a, b) => b.score - a.score);

  console.log(kuler("\n🏆 Check your position on the Leaderboard:\n", "#e11d48"));
  for (let entry of leaderBoard) {
    console.log(kuler(`${entry.name} - ${entry.score}`, "#2563eb"));
  }
}

showQuestionAndOptions(database);
console.log(kuler(`\n🎯 Your final score is: ${score}`, "#16a34a"));
highScore(leaderBoard);
